import os
import re
from PIL import Image, ImageOps, ImageFilter
import pytesseract
from decimal import Decimal, InvalidOperation
from datetime import date

IMG_DIR = '/app/workspace/dataset/img'

EXCLUSION_KEYWORDS = [
    'SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED'
]

PRIORITY_KEYWORDS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

amount_re = re.compile(r'(?<!\d)(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{2})')
amount_re_loose = re.compile(r'(?<!\d)(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{2})?')

month_map = {
    'JAN': 1, 'JANUARY': 1,
    'FEB': 2, 'FEBRUARY': 2,
    'MAR': 3, 'MARCH': 3,
    'APR': 4, 'APRIL': 4,
    'MAY': 5,
    'JUN': 6, 'JUNE': 6,
    'JUL': 7, 'JULY': 7,
    'AUG': 8, 'AUGUST': 8,
    'SEP': 9, 'SEPT': 9, 'SEPTEMBER': 9,
    'OCT': 10, 'OCTOBER': 10,
    'NOV': 11, 'NOVEMBER': 11,
    'DEC': 12, 'DECEMBER': 12,
}


def preprocess(img):
    # Basic preprocessing: grayscale + contrast + threshold
    img = ImageOps.grayscale(img)
    img = ImageOps.autocontrast(img)
    img = img.filter(ImageFilter.MedianFilter(size=3))
    # simple threshold
    img = img.point(lambda p: 255 if p > 180 else 0)
    return img


def ocr_image(path):
    img = Image.open(path)
    text = pytesseract.image_to_string(img)
    # second pass with preprocessing if needed
    if len(text.strip()) < 20:
        img2 = preprocess(img)
        text2 = pytesseract.image_to_string(img2)
        if len(text2.strip()) > len(text.strip()):
            text = text2
    return text


def extract_amount(text):
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    upper_lines = [ln.upper() for ln in lines]

    def has_exclusion(line):
        return any(excl in line for excl in EXCLUSION_KEYWORDS)

    def extract_from_line(line):
        # Prefer amounts with 2 decimals, fallback to looser pattern
        matches = amount_re.findall(line)
        if not matches:
            matches = amount_re_loose.findall(line)
        if not matches:
            return None
        return matches[-1]

    for group in PRIORITY_KEYWORDS:
        for idx, uline in enumerate(upper_lines):
            if has_exclusion(uline):
                continue
            if any(kw in uline for kw in group):
                candidate = extract_from_line(lines[idx])
                if candidate:
                    return candidate
                # try next line if keyword line has no amount
                if idx + 1 < len(lines) and not has_exclusion(upper_lines[idx + 1]):
                    candidate = extract_from_line(lines[idx + 1])
                    if candidate:
                        return candidate
    return None


def normalize_amount(raw):
    if not raw:
        return None
    raw = raw.replace(',', '')
    try:
        dec = Decimal(raw)
    except InvalidOperation:
        return None
    return f"{dec:.2f}"


def extract_date(text):
    candidates = []

    # YYYY-MM-DD or YYYY/MM/DD
    for m in re.finditer(r'(\d{4})[\-/](\d{1,2})[\-/](\d{1,2})', text):
        y, mo, d = map(int, m.groups())
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    # DD-MM-YYYY or DD/MM/YYYY or DD-MM-YY
    for m in re.finditer(r'(\d{1,2})[\-/](\d{1,2})[\-/](\d{2,4})', text):
        d, mo, y = m.groups()
        d = int(d)
        mo = int(mo)
        y = int(y)
        if y < 100:
            y += 2000
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    # Month name formats: 23 JAN 2019
    for m in re.finditer(r'(\d{1,2})\s*([A-Za-z]{3,9})\s*(\d{4})', text):
        d = int(m.group(1))
        mon = m.group(2).upper()
        y = int(m.group(3))
        mo = month_map.get(mon)
        if not mo:
            continue
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    return candidates[0][1].isoformat()


def process_file(path):
    text = ocr_image(path)
    raw_amount = extract_amount(text)
    amount = normalize_amount(raw_amount)
    date_str = extract_date(text)
    return date_str, amount

files = sorted([f for f in os.listdir(IMG_DIR) if f.lower().endswith(('.jpg', '.jpeg', '.png'))])

results = []
for fname in files:
    path = os.path.join(IMG_DIR, fname)
    d, amt = process_file(path)
    results.append((fname, d, amt))

for row in results:
    print(row)
