        if 'AMOUNT' not in line:
            return False
        if any(hw in line for hw in HEADER_WORDS) and not any(k in line for k in ['TOTAL', 'DUE', 'BALANCE', 'NET', 'GRAND']):
            return True
        return False

    def extract_from_line(line):
        # fix 92:80 -> 92.80
        line = re.sub(r'(?<=\d):(?=\d{2}\b)', '.', line)
        matches = amount_re_dot.findall(line)
        if matches:
            return matches[-1]
        matches = amount_re_comma.findall(line)
        if matches:
            return matches[-1]
        matches = amount_re_loose.findall(line)
        if not matches:
            return None
        return matches[-1]

    for group in PRIORITY_KEYWORDS:
        for idx, uline in enumerate(upper_lines):
            if has_exclusion(uline):
                continue
            if any(kw in uline for kw in group):
                if is_header_line(uline):
                    continue
                candidate = extract_from_line(lines[idx])
                if candidate:
                    return candidate
                if idx + 1 < len(lines) and not has_exclusion(upper_lines[idx + 1]):
                    candidate = extract_from_line(lines[idx + 1])
                    if candidate:
                        return candidate
    return None


def normalize_amount(raw):
    if not raw:
        return None
    raw = raw.strip()
    if ',' in raw and '.' in raw:
        # assume comma thousands, dot decimal
        raw = raw.replace(',', '')
    elif ',' in raw and '.' not in raw:
        # assume comma decimal
        raw = raw.replace('.', '')
        raw = raw.replace(',', '.')
    try:
        dec = Decimal(raw)
    except InvalidOperation:
        return None
    return f"{dec:.2f}"


def extract_date(text):
    candidates = []

    for m in re.finditer(r'(\d{4})[\-/](\d{1,2})[\-/](\d{1,2})', text):
        y, mo, d = map(int, m.groups())
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    for m in re.finditer(r'(\d{1,2})[\-/](\d{1,2})[\-/](\d{2,4})', text):
        d, mo, y = m.groups()
        d = int(d)
        mo = int(mo)
        y = int(y)
        if y < 100:
            y += 2000
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    for m in re.finditer(r'(\d{1,2})\s*([A-Za-z]{3,9})\s*(\d{4})', text):
        d = int(m.group(1))
        mon = m.group(2).upper()
        y = int(m.group(3))
        mo = month_map.get(mon)
        if not mo:
            continue
        try:
            dt = date(y, mo, d)
        except ValueError:
            continue
        candidates.append((m.start(), dt))

    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0])
    return candidates[0][1].isoformat()


def process_file(path):
    texts = ocr_texts(path)

    amount = None
    for text in texts:
        raw = extract_amount(text)
        amount = normalize_amount(raw)
        if amount:
            break

    date_str = None
    for text in texts:
        date_str = extract_date(text)
        if date_str:
            break

    return date_str, amount

